content.text:
请对以下 case 进行三维加权评分。

=== case_id ===
Case-09-weather-care-008

=== 用户原始指令 (query.txt) ===
给我弄个卡片整个图带数字变化的，点一下能跳到应用，提醒我快冻死了

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "给我弄个卡片整个图带数字变化的，点一下能跳到应用，提醒我快冻死了",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "",
        "abilityName": "",
        "uri": "hww://www.huawei.com/totemweather?enterType=share&cityCode="
      }
    }
  ],
  "dataModelSchema": {
    "data": {
      "weather": {
        "location": {
          "districtName": {
            "type": "string",
            "description": "区或县名称",
            "sampleValue": "青浦"
          }
        },
        "current": {
          "temperatureText": {
            "type": "string",
            "description": "适合直接显示的当前温度文本",
            "sampleValue": "-8℃"
          },
          "condition": {
            "type": "string",
            "description": "当前天气现象",
            "sampleValue": "小雪"
          },
          "feelsLikeC": {
            "type": "number",
            "description": "当前体感摄氏温度",
            "sampleValue": -11
          },
          "windLevel": {
            "type": "integer",
            "description": "当前风力等级",
            "sampleValue": 4
          },
          "airQuality": {
            "type": "string",
            "description": "当前空气质量等级",
            "sampleValue": "优"
          },
          "coldLevel": {
            "type": "string",
            "description": "感冒指数",
            "sampleValue": "易发"
          },
          "alertLevel": {
            "type": "string",
            "description": "低温预警提醒文本",
            "sampleValue": "快冻死了"
          }
        }
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/snow.png",
      "description": "彩色雪花天气图标，适合用于低温、降雪和寒冷天气状态展示。"
    }
  ]
}

